-- Two extension strands for the Interdisciplinary model: The Nature of Schooling and The Languages of Being Human.
-- Generated by scripts/generate_schooling_language_strands_migration.mjs; do not hand-edit.
--
-- Each strand has four grade-band parts, tagged to the shared concepts and to 17 new proposed concepts, with the four OpenEvo
-- thinking tools woven in (Tinbergen's Questions, Causal Mapping, Payoff Matrices, Analogy Mapping) as threads of stations.
-- Parts have status 'draft', so the comparison views, which read accepted rows only, do not count them. Threads and connections
-- have status 'proposed'. Concepts have status 'proposed'. Accepted records are not changed.
-- Everything is AI-drafted and unreviewed by a subject expert. No classroom has tested it.
-- Source of the design: lab_manager docs/design-notes/interdisciplinary-strands-nature-of-schooling-and-languages-of-being-human-2026-10-30.md.
-- Literature rows are added by a follow-up migration once LiteratureBase holds the sources.

SET search_path = public, extensions;

-- 1. New proposed concepts and their domain meanings
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('57263ccf-8497-508d-a646-85148ba9f4a9', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Education', 'The organised ways a group helps its members take on knowledge, skills, values and ways of taking part in community life. It includes teaching in homes, workplaces and communities as well as in schools.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"level":"extension","definition":"The organised ways a group helps its members take on knowledge, skills, values and ways of taking part in community life. It includes teaching in homes, workplaces and communities as well as in schools.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Education is wider than schooling. Learning can happen without any education, and education can happen with little learning. Years of education are not a measure of intelligence or of a person''s worth.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Culture and Social Structure","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('cb615082-2a72-50b2-be47-5152ab9591fd', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Education (culture)', 'Every known society has ways of passing knowledge to children and newcomers. For most of human history children learned mostly through daily life and joining in adult work. Today nearly every country also runs schools, and people still learn much outside them.', '57263ccf-8497-508d-a646-85148ba9f4a9', '{"level":"discipline-facet","facet_of":"Education","definition":"Every known society has ways of passing knowledge to children and newcomers. For most of human history children learned mostly through daily life and joining in adult work. Today nearly every country also runs schools, and people still learn much outside them.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-education-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2c7d8591-2e34-5f5e-a573-225142981a9b', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Education (education)', 'The field and the practice of helping people learn, in schools and elsewhere, with its own aims, methods and arguments about both.', '57263ccf-8497-508d-a646-85148ba9f4a9', '{"level":"discipline-facet","facet_of":"Education","definition":"The field and the practice of helping people learn, in schools and elsewhere, with its own aims, methods and arguments about both.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-education-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('7f3313a9-e131-5cd9-9e88-3adabd9c26ce', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Schooling', 'Education carried out in a school: a place set apart, with teachers, groups of learners, a timetable and a plan of what to teach. It is one arrangement among many. Schools are several thousand years old, and schooling for nearly every child is recent.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"level":"extension","definition":"Education carried out in a school: a place set apart, with teachers, groups of learners, a timetable and a plan of what to teach. It is one arrangement among many. Schools are several thousand years old, and schooling for nearly every child is recent.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-schooling","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Schooling is not the same as learning or education. It is not a biological adaptation, and nothing in the evolutionary account says schools are where human learning was heading. Other ways of learning are not shortfalls compared with it.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Culture and Social Structure","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bb05f8ce-4e15-59ef-be9e-0c611239848a', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Schooling (culture)', 'A cultural institution that societies built and keep changing. Its form, aims and reach differ between places and periods.', '7f3313a9-e131-5cd9-9e88-3adabd9c26ce', '{"level":"discipline-facet","facet_of":"Schooling","definition":"A cultural institution that societies built and keep changing. Its form, aims and reach differ between places and periods.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-schooling-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('526ce9d4-1581-541e-b844-df492a69a930', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Schooling (education)', 'The organised teaching of groups in schools, with a curriculum, assessment and qualifications.', '7f3313a9-e131-5cd9-9e88-3adabd9c26ce', '{"level":"discipline-facet","facet_of":"Schooling","definition":"The organised teaching of groups in schools, with a curriculum, assessment and qualifications.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-schooling-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('954e3407-019e-58b4-b72d-e7e967a5f20d', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Curriculum', 'A plan for what is to be learned, in what order and how it is checked. The word is also used for what is taught and for what learners end up learning, and researchers keep the three apart: the intended curriculum (the written plan), the implemented curriculum (what is taught) and the attained curriculum (what learners learn). They add the hidden curriculum: what a school teaches without saying so, such as habits, obedience and who counts as clever.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"level":"extension","definition":"A plan for what is to be learned, in what order and how it is checked. The word is also used for what is taught and for what learners end up learning, and researchers keep the three apart: the intended curriculum (the written plan), the implemented curriculum (what is taught) and the attained curriculum (what learners learn). They add the hidden curriculum: what a school teaches without saying so, such as habits, obedience and who counts as clever.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-curriculum","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"A curriculum is not a fixed list of facts. What is written, what is taught and what is learned differ. Choosing what enters a curriculum is a human decision with aims and power behind it, which differs from natural selection, where nobody chooses.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Culture and Social Structure","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d5d2e817-2505-5e4c-b752-19ef3b8a0049', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Curriculum (culture)', 'What a group decides to pass on, and in what form. The decision involves people, groups and aims.', '954e3407-019e-58b4-b72d-e7e967a5f20d', '{"level":"discipline-facet","facet_of":"Curriculum","definition":"What a group decides to pass on, and in what form. The decision involves people, groups and aims.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-curriculum-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('93d81321-7db9-5d12-a979-a6bea2e46139', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Curriculum (education)', 'The written plan, the lessons given and the learning that results. A comparison of two curricula says which of the three it means.', '954e3407-019e-58b4-b72d-e7e967a5f20d', '{"level":"discipline-facet","facet_of":"Curriculum","definition":"The written plan, the lessons given and the learning that results. A comparison of two curricula says which of the three it means.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-curriculum-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('28759b16-c617-5f18-a81c-aaa675b94e8f', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Curriculum (AI and computation)', 'In machine learning, ''curriculum learning'' means ordering training examples from easier to harder. A person or a program sets the order, and the training does not need the program to know there is a plan.', '954e3407-019e-58b4-b72d-e7e967a5f20d', '{"level":"discipline-facet","facet_of":"Curriculum","definition":"In machine learning, ''curriculum learning'' means ordering training examples from easier to harder. A person or a program sets the order, and the training does not need the program to know there is a plan.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-curriculum-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('83aca913-e527-57f7-949c-f63855539d41', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Guided Participation', 'Learning by taking part in a shared activity with adults, older children or peers. Guidance can be spoken or silent, and learners often join in on their own. The others may or may not intend to teach.', '938e144b-1e6a-5027-8292-f19fc111d640', '{"level":"extension","definition":"Learning by taking part in a shared activity with adults, older children or peers. Guidance can be spoken or silent, and learners often join in on their own. The others may or may not intend to teach.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-guided-participation","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Guided participation does not require intentional teaching. It is not a school method only. It does not rank ways of learning: observation, helping and instruction each suit different skills.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Learning, Minds and Discovery","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('52fe6e8e-8883-5d50-bfa2-e945b25555b7', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Guided Participation (culture)', 'A common way children take on skills in many societies, through helping with everyday work and watching those who do them.', '83aca913-e527-57f7-949c-f63855539d41', '{"level":"discipline-facet","facet_of":"Guided Participation","definition":"A common way children take on skills in many societies, through helping with everyday work and watching those who do them.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-guided-participation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e8a3ca58-bfb6-5d73-9b04-291539b8b650', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Guided Participation (cognition)', 'A learner takes on more of a shared task as skill grows, helped by what others do and say and by their own initiative.', '83aca913-e527-57f7-949c-f63855539d41', '{"level":"discipline-facet","facet_of":"Guided Participation","definition":"A learner takes on more of a shared task as skill grows, helped by what others do and say and by their own initiative.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-guided-participation-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d9dff24e-6a29-54a8-acb4-9908a866fdff', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Guided Participation (education)', 'Classroom methods that build on joint activity, such as working together on a task with coaching.', '83aca913-e527-57f7-949c-f63855539d41', '{"level":"discipline-facet","facet_of":"Guided Participation","definition":"Classroom methods that build on joint activity, such as working together on a task with coaching.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-guided-participation-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fc358dcc-5e31-5df7-9573-ff8ba52ef567', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Apprenticeship', 'Learning a skill by taking part in the work alongside experienced workers, with tasks that grow harder as skill grows.', '938e144b-1e6a-5027-8292-f19fc111d640', '{"level":"extension","definition":"Learning a skill by taking part in the work alongside experienced workers, with tasks that grow harder as skill grows.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-apprenticeship","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"The word covers informal learning on the job and formal schemes with contracts. Apprenticeship does not imply low status or a lack of schooling. Work that harms children or keeps them from school is not apprenticeship.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Learning, Minds and Discovery","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('748b6361-53c5-5f86-b41a-c32576b09268', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Apprenticeship (culture)', 'A common way skills such as farming, building, cooking and craft pass between generations, with or without payment or contracts.', 'fc358dcc-5e31-5df7-9573-ff8ba52ef567', '{"level":"discipline-facet","facet_of":"Apprenticeship","definition":"A common way skills such as farming, building, cooking and craft pass between generations, with or without payment or contracts.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-apprenticeship-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('87add493-8a6e-572d-9b95-f3b7c85278d3', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Apprenticeship (education)', 'A formal training scheme that combines work with instruction and a recognised qualification.', 'fc358dcc-5e31-5df7-9573-ff8ba52ef567', '{"level":"discipline-facet","facet_of":"Apprenticeship","definition":"A formal training scheme that combines work with instruction and a recognised qualification.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-apprenticeship-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('62587d95-6f37-5183-95b9-f28f387bd89e', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Educational Purpose', 'A reason a person, group or society gives for why education exists or what it is for. Purposes sit at several levels (the learner, the family, the community, the school, the nation, the world and future generations) and can conflict.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"level":"extension","definition":"A reason a person, group or society gives for why education exists or what it is for. Purposes sit at several levels (the learner, the family, the community, the school, the nation, the world and future generations) and can conflict.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-educational-purpose","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"A stated purpose is not the same as what a system does. Purposes do not all have equal evidence behind them. The levels do not always agree, and naming them does not settle which should win.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Culture and Social Structure","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('07a3b27a-7009-54fa-8a63-43fa59d37bb8', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Educational Purpose (culture)', 'Aims such as passing on a language, a faith or a craft, keeping a community together, or preparing members for change.', '62587d95-6f37-5183-95b9-f28f387bd89e', '{"level":"discipline-facet","facet_of":"Educational Purpose","definition":"Aims such as passing on a language, a faith or a craft, keeping a community together, or preparing members for change.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-educational-purpose-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6522684e-b76f-5d67-a5fe-fa1cb58b9c00', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Educational Purpose (education)', 'Aims written into laws and curricula, such as work skills, citizenship, personal growth and fairness, which are argued over. Some researchers describe three aims that compete: equal citizenship, skills for work, and sorting people for social position.', '62587d95-6f37-5183-95b9-f28f387bd89e', '{"level":"discipline-facet","facet_of":"Educational Purpose","definition":"Aims written into laws and curricula, such as work skills, citizenship, personal growth and fairness, which are argued over. Some researchers describe three aims that compete: equal citizenship, skills for work, and sorting people for social position.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-educational-purpose-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('479fb3a6-1924-5091-a8c4-31b22e69982c', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Literacy', 'The ability to read and write a language and, more widely, to use a written or other symbol system for the tasks a community needs.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"level":"extension","definition":"The ability to read and write a language and, more widely, to use a written or other symbol system for the tasks a community needs.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-literacy","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Literacy is not intelligence. Communities that rely mostly on speech hold knowledge in other forms, such as story, song and apprenticeship. Test scores measure one version of literacy. Schooling and literacy are different things and their effects have been found to differ.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Information, Technology and Collective Systems","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ba0d4001-a39c-59c8-b11d-568223bf1371', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Literacy (culture)', 'Reading and writing take different forms and serve different uses in different communities, from record keeping to religion to letters.', '479fb3a6-1924-5091-a8c4-31b22e69982c', '{"level":"discipline-facet","facet_of":"Literacy","definition":"Reading and writing take different forms and serve different uses in different communities, from record keeping to religion to letters.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-literacy-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('36b9717e-e243-5404-9fa3-25c0070e721f', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Literacy (education)', 'A skill taught in schools, homes and religious settings, and measured in tests and surveys.', '479fb3a6-1924-5091-a8c4-31b22e69982c', '{"level":"discipline-facet","facet_of":"Literacy","definition":"A skill taught in schools, homes and religious settings, and measured in tests and surveys.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-literacy-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8442a295-c209-5bc5-befe-c1afd64c9ae9', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Literacy (technology)', 'Skill with a system of tools for recording and sharing information, which changes as the tools change.', '479fb3a6-1924-5091-a8c4-31b22e69982c', '{"level":"discipline-facet","facet_of":"Literacy","definition":"Skill with a system of tools for recording and sharing information, which changes as the tools change.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-literacy-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6f6f678e-5069-5e01-b317-3f31a2f572f3', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language of Instruction', 'The language in which lessons are taught.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"level":"extension","definition":"The language in which lessons are taught.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-of-instruction","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"The language of instruction is not always a learner''s home language. A choice that suits administration may make learning harder for some children. Research broadly finds that children learn best early on in a language they understand. The effects of switching later depend on the setting.","core_counterparts":[],"curriculum_use":"Used by the Nature of Schooling strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Culture and Social Structure","extension_strand":"nature-of-schooling"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d1794d6a-8122-5516-9bfb-703cac6f0695', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language of Instruction (culture)', 'A choice about which languages carry knowledge in public life. It affects which languages are used and passed on. Schooling has been used to move children away from the languages of their families, and some communities have asked for schools to teach their languages.', '6f6f678e-5069-5e01-b317-3f31a2f572f3', '{"level":"discipline-facet","facet_of":"Language of Instruction","definition":"A choice about which languages carry knowledge in public life. It affects which languages are used and passed on. Schooling has been used to move children away from the languages of their families, and some communities have asked for schools to teach their languages.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-of-instruction-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('335b4e0b-e224-5aeb-a3ba-38b06ee9fda7', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language of Instruction (education)', 'A choice made by schools or governments that affects who can follow lessons and how well.', '6f6f678e-5069-5e01-b317-3f31a2f572f3', '{"level":"discipline-facet","facet_of":"Language of Instruction","definition":"A choice made by schools or governments that affects who can follow lessons and how well.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-of-instruction-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('dcacbe0f-6ddd-58b1-b63a-a91ebb7e46ee', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language', 'A shared system of signs, spoken, signed or written, that a community uses to communicate and to hold and pass on knowledge. Children learn a language from the people around them.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"level":"extension","definition":"A shared system of signs, spoken, signed or written, that a community uses to communicate and to hold and pass on knowledge. Children learn a language from the people around them.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Calls, programming languages and the output of language models are not human languages, even where they share some features. Sign languages are full languages, and they differ from one another. A language and a nation are different things.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Information, Technology and Collective Systems","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3656af1a-b8fe-5149-802b-383668d882c1', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language (biology)', 'Some animals have rich call systems. Researchers disagree about how far these resemble human language, and the question is not settled.', 'dcacbe0f-6ddd-58b1-b63a-a91ebb7e46ee', '{"level":"discipline-facet","facet_of":"Language","definition":"Some animals have rich call systems. Researchers disagree about how far these resemble human language, and the question is not settled.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9f6e2683-2eb6-52b3-8deb-882c2cf33033', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language (culture)', 'A set of conventions a community shares and keeps changing as its speakers use it.', 'dcacbe0f-6ddd-58b1-b63a-a91ebb7e46ee', '{"level":"discipline-facet","facet_of":"Language","definition":"A set of conventions a community shares and keeps changing as its speakers use it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1260f43a-cf8c-55a2-be20-1d87e4ab5d01', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language (cognition)', 'A skill for understanding and producing sentences, learned in childhood by hearing or seeing a language.', 'dcacbe0f-6ddd-58b1-b63a-a91ebb7e46ee', '{"level":"discipline-facet","facet_of":"Language","definition":"A skill for understanding and producing sentences, learned in childhood by hearing or seeing a language.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('75387c73-5146-576a-a4f6-45d017d5d439', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language (technology)', 'A formal language, such as a programming language, has fixed rules that designers wrote.', 'dcacbe0f-6ddd-58b1-b63a-a91ebb7e46ee', '{"level":"discipline-facet","facet_of":"Language","definition":"A formal language, such as a programming language, has fixed rules that designers wrote.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('5086f91b-62d8-55f9-8c4b-f8a45455066a', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language (AI and computation)', 'A language model predicts likely next words from large amounts of text. It produces language-like output. Whether that amounts to understanding is debated, and fluent output alone does not settle it.', 'dcacbe0f-6ddd-58b1-b63a-a91ebb7e46ee', '{"level":"discipline-facet","facet_of":"Language","definition":"A language model predicts likely next words from large amounts of text. It produces language-like output. Whether that amounts to understanding is debated, and fluent output alone does not settle it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0d2378d6-1ac6-5329-8b05-86147f318fea', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Word Meaning', 'What a word or sign stands for among the people who use it. Many words have several related meanings, and meanings shift over time and with setting.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"level":"extension","definition":"What a word or sign stands for among the people who use it. Many words have several related meanings, and meanings shift over time and with setting.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-word-meaning","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"The closest word in another language often covers a different range of meanings. A dictionary translation is a summary of a meaning. One word with several meanings does not show that the speakers confuse them.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Information, Technology and Collective Systems","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('410826b7-58ca-5dcf-9725-9f54910c65d5', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Word Meaning (culture)', 'The shared understanding of a word in a community, which changes as the community changes.', '0d2378d6-1ac6-5329-8b05-86147f318fea', '{"level":"discipline-facet","facet_of":"Word Meaning","definition":"The shared understanding of a word in a community, which changes as the community changes.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-word-meaning-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('012846bf-7550-5bab-8866-3b5f539feca6', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Word Meaning (cognition)', 'The ideas a listener links with a word, which differ a little from person to person.', '0d2378d6-1ac6-5329-8b05-86147f318fea', '{"level":"discipline-facet","facet_of":"Word Meaning","definition":"The ideas a listener links with a word, which differ a little from person to person.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-word-meaning-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e1f5fc1b-7ae8-5267-854a-6394b7e4d7cb', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Borrowing', 'Taking a word, sound or structure from another language into one''s own.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"level":"extension","definition":"Taking a word, sound or structure from another language into one''s own.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-borrowing","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Borrowing is a different route from inheritance from a common ancestor, so a word shared by two languages may have come by either route. Borrowing is normal and does not make a language lesser.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Culture and Social Structure","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c1c23fe8-9fb5-587a-835c-3834e0263254', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Borrowing (culture)', 'Loanwords travel with goods, ideas, religions and technologies, and become part of the borrowing language.', 'e1f5fc1b-7ae8-5267-854a-6394b7e4d7cb', '{"level":"discipline-facet","facet_of":"Borrowing","definition":"Loanwords travel with goods, ideas, religions and technologies, and become part of the borrowing language.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-borrowing-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ef3118e2-59b7-53d7-818d-1b4fe9ef1736', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Translation', 'Expressing what was said or written in one language in another language.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"level":"extension","definition":"Expressing what was said or written in one language in another language.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-translation","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"A translation is a judgement. It rarely matches word for word. A draft translation by software or by an AI helper needs review by a speaker of both languages before anyone relies on it.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Information, Technology and Collective Systems","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3db748c3-7e4f-528d-ada1-e972e558c0fe', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Translation (culture)', 'A skill and a trade that keeps ideas moving between communities and always involves choices.', 'ef3118e2-59b7-53d7-818d-1b4fe9ef1736', '{"level":"discipline-facet","facet_of":"Translation","definition":"A skill and a trade that keeps ideas moving between communities and always involves choices.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-translation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('316547ba-8748-53dd-afbb-74d4684b3a15', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Translation (AI and computation)', 'Machine translation maps text to text using patterns learned from examples. Its output can read well and still be wrong, and fluent output alone does not settle whether the software understands.', 'ef3118e2-59b7-53d7-818d-1b4fe9ef1736', '{"level":"discipline-facet","facet_of":"Translation","definition":"Machine translation maps text to text using patterns learned from examples. Its output can read well and still be wrong, and fluent output alone does not settle whether the software understands.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-translation-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('cb666457-4ecf-5c4e-be1b-e2aa2f956d51', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language Family', 'A group of languages that descend from one earlier language.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"level":"extension","definition":"A group of languages that descend from one earlier language.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-family","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"A family tree of languages is a partial picture. It hides borrowing between branches and says nothing about the biological ancestry of speakers. Languages are not organisms. Languages in one family are not fully independent examples when testing a claim.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"The Evolutionary Pattern","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('01c4d7f5-3e13-5e5d-a91e-3a50405bfc97', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language Family (biology)', 'A tree of descent resembles a tree of living things in that groups share an origin, and differs in that languages borrow across branches and speakers can change a language on purpose.', 'cb666457-4ecf-5c4e-be1b-e2aa2f956d51', '{"level":"discipline-facet","facet_of":"Language Family","definition":"A tree of descent resembles a tree of living things in that groups share an origin, and differs in that languages borrow across branches and speakers can change a language on purpose.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-family-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c22ca375-da4b-576d-81ac-907afec26c35', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language Family (culture)', 'A grouping of languages that gives clues to the history of speaker movement and contact. Languages also spread when people switch languages without moving.', 'cb666457-4ecf-5c4e-be1b-e2aa2f956d51', '{"level":"discipline-facet","facet_of":"Language Family","definition":"A grouping of languages that gives clues to the history of speaker movement and contact. Languages also spread when people switch languages without moving.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-family-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('18024a52-8071-5d85-8614-410a82cddcbd', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Writing System', 'A set of marks and rules used to record a language, such as an alphabet, a syllabary, a set of characters or a script that writes consonants with marks for vowels.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"level":"extension","definition":"A set of marks and rules used to record a language, such as an alphabet, a syllabary, a set of characters or a script that writes consonants with marks for vowels.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-writing-system","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Writing records language and is not language itself. Many languages have no written form, and one language can be written in more than one script. Not having writing does not make a language or a culture less developed.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Information, Technology and Collective Systems","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('41b54f57-52b5-5403-b14f-6580b525ba60', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Writing System (culture)', 'A tool a community uses to keep records and pass on texts. Communities adopt, adapt and sometimes replace scripts.', '18024a52-8071-5d85-8614-410a82cddcbd', '{"level":"discipline-facet","facet_of":"Writing System","definition":"A tool a community uses to keep records and pass on texts. Communities adopt, adapt and sometimes replace scripts.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-writing-system-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1aecf9df-4bca-55de-a0fb-768393dc84b2', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Writing System (technology)', 'A recording technology, whose form shapes what is easy to copy, store and search.', '18024a52-8071-5d85-8614-410a82cddcbd', '{"level":"discipline-facet","facet_of":"Writing System","definition":"A recording technology, whose form shapes what is easy to copy, store and search.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-writing-system-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('785dd3d3-9b2f-52b3-99f0-1f665a3743a1', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Multilingualism', 'Using more than one language in daily life.', '7c3323f6-9afd-54ba-a6ba-0f6b09ced583', '{"level":"extension","definition":"Using more than one language in daily life.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-multilingualism","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Multilingualism is not a deficit or a delay. A multilingual person does not hold the languages in sealed compartments. A country or a school does not have one language only because its official documents use one.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Culture and Social Structure","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6ac80120-277b-5e83-b69c-2a99f0d230b2', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Multilingualism (culture)', 'A normal condition in many parts of the world, where people use different languages with family, neighbours, in markets and in school.', '785dd3d3-9b2f-52b3-99f0-1f665a3743a1', '{"level":"discipline-facet","facet_of":"Multilingualism","definition":"A normal condition in many parts of the world, where people use different languages with family, neighbours, in markets and in school.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-multilingualism-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0be5f54f-2ff6-5b17-91f9-fec0cdd75c23', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Multilingualism (cognition)', 'A person who uses several languages draws on them according to the listener and the setting.', '785dd3d3-9b2f-52b3-99f0-1f665a3743a1', '{"level":"discipline-facet","facet_of":"Multilingualism","definition":"A person who uses several languages draws on them according to the listener and the setting.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-multilingualism-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2c027a3d-747d-5fe0-bb22-e6d9287923da', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Multilingualism (education)', 'Learners who use several languages arrive at school with resources, and the language of instruction decides how much of those resources the school uses.', '785dd3d3-9b2f-52b3-99f0-1f665a3743a1', '{"level":"discipline-facet","facet_of":"Multilingualism","definition":"Learners who use several languages arrive at school with resources, and the language of instruction decides how much of those resources the school uses.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-multilingualism-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('71e6fe9a-dbdd-5d9b-b9a3-6dccdea9b2f6', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'One Word, Two Meanings', 'A single word that covers two meanings in one language, such as a word for both time and weather. Researchers call this colexification and study which meanings share words across many languages.', 'c9290170-3f1d-5e74-8a4d-3864d2ca6a18', '{"level":"extension","definition":"A single word that covers two meanings in one language, such as a word for both time and weather. Researchers call this colexification and study which meanings share words across many languages.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-one-word-two-meanings","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"A shared word shows how a language packages meanings. It does not show that speakers confuse the two meanings. Sharing can come from ancestry, borrowing or chance, so it takes a wide, well-spread sample of languages to say anything general.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"Information, Technology and Collective Systems","extension_strand":"languages-of-being-human"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6bcf0de5-0da2-5fe1-b885-9ed384bf46d0', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'One Word, Two Meanings (culture)', 'A pattern in how a language packages meanings, which can point to metaphors, history or contact.', '71e6fe9a-dbdd-5d9b-b9a3-6dccdea9b2f6', '{"level":"discipline-facet","facet_of":"One Word, Two Meanings","definition":"A pattern in how a language packages meanings, which can point to metaphors, history or contact.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-one-word-two-meanings-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ccd56038-ac43-597d-a7c7-2e49be2cf6d2', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'One Word, Two Meanings (cognition)', 'A prompt for questions about how speakers link two ideas, to be tested with other kinds of evidence.', '71e6fe9a-dbdd-5d9b-b9a3-6dccdea9b2f6', '{"level":"discipline-facet","facet_of":"One Word, Two Meanings","definition":"A prompt for questions about how speakers link two ideas, to be tested with other kinds of evidence.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-one-word-two-meanings-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('93944410-8293-5bc8-935c-94ad0ff5cabf', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language Evolution', 'The process by which languages change, diversify and descend from common ancestral languages over time, through transmission with variation of the kind that shapes other cultural traits.', 'ab896065-5feb-5fb9-ad34-a8599ddf6049', '{"level":"extension","definition":"The process by which languages change, diversify and descend from common ancestral languages over time, through transmission with variation of the kind that shapes other cultural traits.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-evolution","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","excludes":"Language change differs from biological evolution: words move sideways between languages, the copied units (words, sounds, patterns) are fuzzier than genes and copied less exactly, and speakers sometimes change a language on purpose. The family tree picture is partial. A change in a language is not progress.","core_counterparts":[],"curriculum_use":"Used by the Languages of Being Human strand.","grounding":["AI-drafted on 2026-10-30 from the lab design note. Sources are attached once LiteratureBase holds them."],"confidence":"low","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","organizing_concept":"The Evolutionary Pattern","extension_strand":"languages-of-being-human","sandbox_conceptbase_id":"OE-SANDBOX-CONCEPT-000003"}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f5a98005-e982-5260-9a93-aea1824e050d', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'concept', 'Language Evolution (culture)', 'Words, sounds and structures change as speakers copy, vary and borrow them, with no central author.', '93944410-8293-5bc8-935c-94ad0ff5cabf', '{"level":"discipline-facet","facet_of":"Language Evolution","definition":"Words, sounds and structures change as speakers copy, vary and borrow them, with no central author.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-language-evolution-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-30","grounding":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;

-- 2. Strand and part records (status draft)
INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('4dba2f37-8343-5a95-8180-ec785af885fb', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'strand', 'The Nature of Schooling', 'Every society passes knowledge to its next generation. Schools are several thousand years old and were for a few children. Schooling for nearly every child is recent, a matter of the last two centuries or so, and began at different times in different countries. This strand asks what is passed on, who teaches, who decides and for whose benefit, in many settings, with schools treated as one case among several. It reuses Teaching, Scaffolding, Institutions, Norms, Knowledge and Development, which the first four strands use but never place at the centre of a part. It does not treat school as the standard that other ways of learning are measured against, and it does not claim that schooling is an adaptation. Many children still have no place in a school and many families want one, so missing school is also a question of justice.', 'K-12', 'Social Studies, Biology', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-nature-of-schooling","description":"Every society passes knowledge to its next generation. Schools are several thousand years old and were for a few children. Schooling for nearly every child is recent, a matter of the last two centuries or so, and began at different times in different countries. This strand asks what is passed on, who teaches, who decides and for whose benefit, in many settings, with schools treated as one case among several. It reuses Teaching, Scaffolding, Institutions, Norms, Knowledge and Development, which the first four strands use but never place at the centre of a part. It does not treat school as the standard that other ways of learning are measured against, and it does not claim that schooling is an adaptation. Many children still have no place in a school and many families want one, so missing school is also a question of justice.","associatedDomains":["Social Studies","Biology","Computer Science"],"epistemicStatus":"designed-thought-experiment","track":"extension-strands","connecting_idea":"Education is wider than schooling. Learning, teaching, education and schooling are four different things, and the strand keeps them apart from the first part to the last.","narrative":"Questions that run through the bands: How do people learn, and who or what helps? What separates learning, teaching, education and schooling? Who decides what is worth passing on? What are schools for, and what happens when their purposes conflict? How do tools, including AI, change what can be passed on? The 6-8 and 9-12 parts use a layered frame of purposes (the learner, the family, the community, the school, the nation, the world and future generations) and allow the layers to disagree. The 9-12 part asks where evolutionary accounts of teaching and transmission have been applied to schools, and where critics say they leave out justice, care, power and who decides.","guardrails":["Do not present school as the standard that other ways of learning are graded against.","Do not describe the practices of any named community. Consultation with that community has to come first.","Do not call schooling an adaptation or say it is where human learning was heading.","Do not suggest that families who want schooling for their children are mistaken.","Keep teaching in other species separate from intentional instruction by people."],"draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","relations":{"builtOnStrands":["agency-development-and-niche-construction","culture-technology-and-collective-systems"]},"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('bffa8eae-478f-52ae-a5fd-b7ff43840af0', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'People Who Show Us How', 'Key concepts: Learning, Teaching, Culture, Guided Participation', 'K-2', 'Social Studies', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-nature-of-schooling-k2","track":"extension-strands","required":true,"performanceIndicators":["Names ways a child learns something from a family member or neighbour, such as watching, helping, playing or being told.","Tells about something learned outside a classroom and who helped.","Says what a person does to help someone learn, such as showing, telling, letting them try or correcting.","Notes that families and places can differ in how they help children learn the same kind of thing."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-learning","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-teaching","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-culture","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-guided-participation","emphasis":"reinforcing"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-learning-discovery","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"reinforcing"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not present school as the standard that other ways of learning are graded against.","Do not describe the practices of any named community. Consultation with that community has to come first.","Do not call schooling an adaptation or say it is where human learning was heading.","Do not suggest that families who want schooling for their children are mistaken.","Keep teaching in other species separate from intentional instruction by people."],"assessmentItem":{"prompt":"Think of something you can do now that you could not do last year. Who or what helped you learn it? What did they do?","goodAnswerShows":"Names a helper or a way of learning (watching, trying, being told) and one thing the helper did.","commonMisreading":"Naming only a teacher is fine. Ask who or what else helped."},"thinkingTools":[{"tool":"Tinbergen''s Questions","level":"precursor","move":"Children choose something they learned, such as tying a shoe, cooking rice or a song. Two question cards guide them: what is it for, and who or what helped, if anyone? They place picture cards on a strip: now, when I was little, before I was born."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
