INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('495058e6-87bd-59ae-a20d-bc2d291fff41', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'Many Places to Learn, Many Ways to Teach', 'Key concepts: Teaching, Scaffolding, Culture, Learning, Apprenticeship, Guided Participation', '3-5', 'Social Studies', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-nature-of-schooling-35","track":"extension-strands","required":true,"performanceIndicators":["Compares how one skill, such as cooking a dish, caring for an animal, reading or playing a sport, is learned in two settings, and says who teaches in each.","Describes with one example how a helper gives less support as a learner improves.","Tells apart a person learning with no one teaching, a lesson that leads to learning, and a lesson that does not.","Names one thing a classroom does well and one thing another setting does well."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-teaching","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-scaffolding","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-culture","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-learning","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-apprenticeship","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-guided-participation","emphasis":"reinforcing"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-learning-discovery","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"reinforcing"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not present school as the standard that other ways of learning are graded against.","Do not describe the practices of any named community. Consultation with that community has to come first.","Do not call schooling an adaptation or say it is where human learning was heading.","Do not suggest that families who want schooling for their children are mistaken.","Keep teaching in other species separate from intentional instruction by people."],"assessmentItem":{"prompt":"Two children learn to ride a bicycle. One is taught by a parent who holds the seat and lets go. The other watches older children and tries alone. Compare what each learner and each helper does.","goodAnswerShows":"Separates the helper''s actions from the learner''s actions, and notes that support shrinks as skill grows in the first case.","commonMisreading":"Treating one way as better. The part asks for a comparison of what each way does, with no ranking."},"thinkingTools":[{"tool":"Causal Mapping","level":"full","move":"Students extend the learner-helper loop (skill rises, help falls) to two settings: a lesson at school and learning beside an older relative at work. Each arrow gets a sign. Each arrow is also marked with who decides it: the teacher''s plan, the helper''s judgement or nobody."},{"tool":"Analogy Mapping","level":"full","move":"Students fill a two-column map: scaffolding on a building and the help a learner gets. Rows: what the support is for, when it is added, when it is taken away, who decides. The break column names the Teaching note, because Scaffolding has no note of its own: a wall takes no part in its own building, and a learner acts, can ask and can refuse."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
