INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('712e4748-73c1-5809-8cbe-8fa0528b138b', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'Why Societies Build Schools', 'Key concepts: Institutions, Knowledge, Norms, Selection, Education, Schooling, Curriculum, Educational Purpose, Language of Instruction, Literacy', '6-8', 'Social Studies, Biology', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-nature-of-schooling-68","track":"extension-strands","required":true,"performanceIndicators":["Describes schooling as one way societies organise education and uses a timeline to show that schools are old and that schooling for nearly every child is recent.","Gives two purposes people have claimed for schools, such as job skills, shared citizenship, sorting people for jobs and positions, passing on a language or faith, or fairness, and describes a case where they conflict.","Explains that what a school teaches is chosen by people and groups, and names who takes part in the choice in one example.","Separates the curriculum as written, as taught and as learned, using one example, and gives one example of something a school teaches without saying so.","Describes how the choice of language of instruction helps some learners and makes learning harder for others."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-institutions","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-knowledge","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-norms","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-selection","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-education","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-schooling","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-curriculum","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-educational-purpose","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-language-of-instruction","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-literacy","emphasis":"reinforcing"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-information-technology","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-evolutionary-pattern","emphasis":"reinforcing"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not present school as the standard that other ways of learning are graded against.","Do not describe the practices of any named community. Consultation with that community has to come first.","Do not call schooling an adaptation or say it is where human learning was heading.","Do not suggest that families who want schooling for their children are mistaken.","Keep teaching in other species separate from intentional instruction by people."],"assessmentItem":{"prompt":"A town argues about adding a subject to its school timetable. List two groups who might care and what each might want. Which of these wants are about the learner, which about the town, which about the country?","goodAnswerShows":"Names at least two groups with different aims and places the aims at different levels, without declaring one group right.","commonMisreading":"Reading ''selection'' as natural selection. The part says people choose what is taught, and the choice has an author."},"thinkingTools":[{"tool":"Tinbergen''s Questions","level":"full","move":"Students put a school and a family workshop side by side in a two-column grid. Rows: what it does for the people involved, how it runs day to day, how a learner comes to it over the years, and where it came from over many years. Rows that do not fit are marked empty with a reason."},{"tool":"Causal Mapping","level":"full","move":"Students map why people at a school add or drop a subject: families ask for it, teachers are available or not, hours in the day are fixed, and an exam rewards some subjects. They mark the delay between a request and a timetable change, and who decides each arrow."},{"tool":"Payoff Matrices","level":"full","move":"Students fill a table in which an education authority picks the language for lessons (the home language, a wider language, or both) and families then choose to enrol, move or pay for a school elsewhere. Cells rank outcomes best, middle and worst for learners, families and the authority, now and later. They look for an arrangement that none of the sides proposed at first."},{"tool":"Analogy Mapping","level":"full","move":"Students compare three stand-ins for what some people chose to pass on: a written curriculum, a textbook and a teacher''s lessons. Rows: what is kept, what is left out, who treats it as a stand-in. The break column uses the Representation note and the Curriculum note: the written plan, the lesson given and the learning that results are three different things."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
