INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('a9c1777a-a159-534d-b927-ad30da661ce6', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'Education as a Changing System', 'Key concepts: Institutions, Selection, Transmission, Innovation, Knowledge, Culture, Educational Purpose, Curriculum, Learning, Metacognition, Technology', '9-12', 'Social Studies, Science, Computer Science', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-nature-of-schooling-912","track":"extension-strands","required":true,"performanceIndicators":["Evaluates a claim that schooling improves a named outcome such as literacy, earnings or health, says what evidence would support it, and names two other explanations, such as a shared cause or an effect running the other way.","Uses the layers of purposes (learner, family, community, school, nation, world, future generations) to analyse a policy argument and shows where the layers pull in different directions.","Describes where evolutionary accounts of teaching and transmission have been applied to schools, such as what spreads and what is kept, and where critics say they leave out justice, care and power.","Compares two accounts of why education systems changed over time, such as the need for skilled workers, the building of states, the passing on of class position, or competition for credentials, and says what evidence would help choose between them.","Analyses how a tool such as AI writing or translation software changes what must be taught, what can be copied and who decides, naming one benefit and one risk, and says what is still debated about what the software does."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-institutions","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-selection","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-transmission","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-innovation","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-knowledge","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-culture","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-educational-purpose","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-curriculum","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-learning","emphasis":"reinforcing"},{"id":"OE-SANDBOX-CONCEPT-000011","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-technology","emphasis":"reinforcing"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-evolutionary-pattern","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-information-technology","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-learning-discovery","emphasis":"reinforcing"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not present school as the standard that other ways of learning are graded against.","Do not describe the practices of any named community. Consultation with that community has to come first.","Do not call schooling an adaptation or say it is where human learning was heading.","Do not suggest that families who want schooling for their children are mistaken.","Keep teaching in other species separate from intentional instruction by people."],"assessmentItem":{"prompt":"A report says that countries with more years of schooling have higher incomes. Draw the causal map the report assumes. Add two other arrows that could produce the same pattern, and mark who or what decides each arrow. State what study would help separate them.","goodAnswerShows":"Marks each arrow as measured or supposed, includes at least one reverse or shared cause, and names a study design.","commonMisreading":"Taking the correlation as proof, or dismissing the claim without saying what evidence would settle it."},"thinkingTools":[{"tool":"Tinbergen''s Questions","level":"extended","move":"Students take one AI tool used for study and ask the grid questions. Rows are renamed for machines: inputs and rules, training and updates, lineage of versions, and what builders and learners gain. They mark rows that do not apply and rows where the answer is unknown, such as the training data."},{"tool":"Causal Mapping","level":"extended","move":"Students map the claim that more years of schooling raise income. They add other causes that could produce the same pattern: family wealth, local jobs, and income paying for more schooling. They mark each arrow as measured or supposed, say who decides it (employers, families, a government or nobody), and name a study that could help separate them."},{"tool":"Payoff Matrices","level":"extended","move":"Students fill a table for two adults who can each spend time teaching a child or doing other work. Both gain if the child learns. Each gains most if the other carries the teaching. They compare ways a group might handle it: a custom, a shared payment, a school, or children learning alongside the work. They say which of these the table fits and which it misses."},{"tool":"Analogy Mapping","level":"extended","move":"Students test whether a teaching method spreading between schools works like a trait spreading in a population. They fill the break column first from the notes on Selection, Fitness, Inheritance and Institutions: who sets the target, whether versions are copied or designed, whether any lineage dies out. Then they fill the match column and keep or drop the words ''variation'', ''selection'' and ''fitness''."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
