INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('19a6d1e8-96b6-58c9-8dff-f68b0ad2fe84', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'strand', 'The Languages of Being Human', 'Every human group has language. Languages differ in how they package meanings, and they share a great deal. This strand asks how language carries knowledge across people and time, how languages change and relate, and what can and cannot be concluded from differences between them. It reuses Communication, Representation, Information, Signal, Cue and Meaning, which the information work of October 2026 placed in the model, and gives them a concrete subject. Sign languages count as full languages from the first part.', 'K-12', 'Language Arts, Social Studies', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-languages-of-being-human","description":"Every human group has language. Languages differ in how they package meanings, and they share a great deal. This strand asks how language carries knowledge across people and time, how languages change and relate, and what can and cannot be concluded from differences between them. It reuses Communication, Representation, Information, Signal, Cue and Meaning, which the information work of October 2026 placed in the model, and gives them a concrete subject. Sign languages count as full languages from the first part.","associatedDomains":["Language Arts","Social Studies","Computer Science"],"epistemicStatus":"designed-thought-experiment","track":"extension-strands","connecting_idea":"Words are shared habits within a community. One word can carry several meanings, one meaning can have several words, and similar words in two languages can come from shared ancestry, borrowing or chance.","narrative":"Questions that run through the bands: How can many different words and signs do the same job? How does a message change as it passes from person to person? Why are two languages alike: shared ancestry, borrowing or chance? What does a word mean, and what is lost in translation? What can differences between languages show about how people think, and what can they not show? The 9-12 part treats the question of independent samples as a statistics lesson: languages in one family share ancestry and neighbours share contact, so agreement among them is weaker evidence than it looks.","guardrails":["Do not treat a word that two languages have in common as evidence that the speakers think alike.","Do not present a translation table as a set of equivalents. Show it as a draft that a speaker of both languages has to check.","Do not say that translation or language software understands, and do not say it cannot. Whether it does is debated, and fluent output alone does not settle it.","Do not claim how speakers of a named language think or live from features of their language. Word examples are fine once a speaker has checked them."],"draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.","relations":{"builtOnStrands":["inheritance-variation-selection-across-systems","culture-technology-and-collective-systems"]},"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('5b73aa4d-166f-5856-bd57-b6e9aa396bde', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'Many Ways to Say It', 'Key concepts: Communication, Representation, Signal, Culture, Language', 'K-2', 'Language Arts, Social Studies', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-languages-of-being-human-k2","track":"extension-strands","required":true,"performanceIndicators":["Shows that people in the class or community say the same thing in different languages or signs, and that a word works because a group shares the habit of using it.","Tells a spoken word, a written word and a sign for the same thing apart from a gesture or an animal call, and says who understands each.","Names a way to share a message with someone who does not share a language, such as pointing, drawing or asking a helper."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-communication","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-representation","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-signal","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-culture","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-language","emphasis":"primary"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-information-technology","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-communication","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"reinforcing"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not treat a word that two languages have in common as evidence that the speakers think alike.","Do not present a translation table as a set of equivalents. Show it as a draft that a speaker of both languages has to check.","Do not say that translation or language software understands, and do not say it cannot. Whether it does is debated, and fluent output alone does not settle it.","Do not claim how speakers of a named language think or live from features of their language. Word examples are fine once a speaker has checked them."],"assessmentItem":{"prompt":"Show three ways to say or show ''water'' to a friend. Which of these would a stranger understand without help? Why?","goodAnswerShows":"Includes more than one language or a sign, and notes that a shared habit is what makes a word work, while pointing is widely understood though people point in different ways.","commonMisreading":"Assuming one language is the original and the others are copies of it."},"thinkingTools":[{"tool":"Tinbergen''s Questions","level":"precursor","move":"Children compare a greeting word from a home language, a sign and a bird''s alarm call. For each they answer what is it for and who passed it on. They see that a person taught the greeting and that people in the group use it the same way."},{"tool":"Payoff Matrices","level":"precursor","move":"Two children each pick one of two made-up words for ''start the game''. A picture table with face cards shows what happens when both pick the same word and when they pick different words. Children say which outcomes they like and what they could do to match."},{"tool":"Analogy Mapping","level":"precursor","move":"Children compare a handshake and a word with picture cards. They sort what is the same (both work because two people know the same rule) from what looks alike and what differs. An adult helps them name one difference."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
