INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('31b3931a-5cfe-5bdd-9a66-5fa460a63392', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'Words Travel and Change', 'Key concepts: Transmission, Variation, Representation, Language, Borrowing, Word Meaning, Writing System', '3-5', 'Language Arts, Social Studies', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-languages-of-being-human-35","track":"extension-strands","required":true,"performanceIndicators":["Passes a message along a chain of at least five people, records how it changed, and says which changes came from mishearing and which from retelling in one''s own way.","Gives an example of a word that moved from one language to another and says what it was used for.","Shows that a word can have more than one meaning in one language and that the same meaning can have different words in other languages.","Compares two ways of writing the same word and names one thing that is easier and one that is harder in each."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-transmission","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-variation","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-representation","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-language","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-borrowing","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-word-meaning","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-writing-system","emphasis":"reinforcing"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-evolutionary-pattern","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-information-technology","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"primary"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not treat a word that two languages have in common as evidence that the speakers think alike.","Do not present a translation table as a set of equivalents. Show it as a draft that a speaker of both languages has to check.","Do not say that translation or language software understands, and do not say it cannot. Whether it does is debated, and fluent output alone does not settle it.","Do not claim how speakers of a named language think or live from features of their language. Word examples are fine once a speaker has checked them."],"assessmentItem":{"prompt":"Pick a word with two meanings that feel connected, like the foot of a person and the foot of a hill. Find out whether another language uses one word or two for those meanings. What does this tell you about words?","goodAnswerShows":"States that the same word can cover different ranges of meaning in different languages, and that finding one example does not give a rule.","commonMisreading":"Concluding that the language with one word has a ''simpler'' idea."},"thinkingTools":[{"tool":"Causal Mapping","level":"full","move":"Students map the message chain from the strand. A noisy room lowers how well each person hears. Interest raises how much detail they add. Each arrow is marked by colour: nobody chose it (mishearing) or a person chose it (retelling in their own words)."},{"tool":"Analogy Mapping","level":"full","move":"Students map a word that moved from one language to another beside a tool that moved from one group to another. Rows: who holds it, who gets it, what changes on arrival, whether it can go back. The break column uses the Transmission note and the Borrowing note: nothing is handed back, and the new language reshapes the word to its own sounds."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
