INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('96a0304e-2ff9-54cb-bbb1-1b03d521e818', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'Languages Have Families and Neighbours', 'Key concepts: Language Evolution, Inheritance, Variation, Analogical Reasoning, Borrowing, Language Family, Translation, Word Meaning, Multilingualism', '6-8', 'Language Arts, Social Studies, Biology', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-languages-of-being-human-68","track":"extension-strands","required":true,"performanceIndicators":["Tells apart four reasons two languages can have a similar word, namely a common ancestor, borrowing, a word that imitates a sound or comes from baby talk, and chance, and gives one example of each.","Reads a small table of related words from two or three languages of one family and describes the pattern of similarity.","Compares a family tree of languages with a family tree of living things, naming two things the tree shows well and two things it hides, such as borrowing across branches and deliberate change.","Shows with a translation example that the closest word in another language often covers a different range of meaning.","Describes how a person who knows several languages uses each with different people and in different places."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-language-evolution","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-inheritance","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-variation","emphasis":"reinforcing"},{"id":"OE-SANDBOX-CONCEPT-000013","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-borrowing","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-language-family","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-translation","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-word-meaning","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-multilingualism","emphasis":"reinforcing"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-evolutionary-pattern","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-learning-discovery","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-information-technology","emphasis":"reinforcing"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not treat a word that two languages have in common as evidence that the speakers think alike.","Do not present a translation table as a set of equivalents. Show it as a draft that a speaker of both languages has to check.","Do not say that translation or language software understands, and do not say it cannot. Whether it does is debated, and fluent output alone does not settle it.","Do not claim how speakers of a named language think or live from features of their language. Word examples are fine once a speaker has checked them."],"assessmentItem":{"prompt":"Two languages have a similar word for the same thing. Give four possible reasons, and say what extra information would help you tell them apart.","goodAnswerShows":"Names ancestry, borrowing, sound imitation or baby talk, and chance, and asks for the history of the word, further related languages or the sound pattern.","commonMisreading":"Treating similarity as proof of shared ancestry, or treating a family tree of languages as a record of who is related by blood."},"thinkingTools":[{"tool":"Tinbergen''s Questions","level":"full","move":"Students ask four questions about one word that travelled between languages: what is it used for, how is it said and understood today, how does a child come to know it, and where did it come from over centuries. They mark how the word reached each language: inherited from an ancestor or borrowed."},{"tool":"Causal Mapping","level":"full","move":"Students draw four different causal stories for one word that two languages have in common: common ancestor, borrowing, imitation of a sound or baby talk, and chance. Each arrow says who or what decides it: children learning the word from their families (ancestor), speakers choosing to take it over (borrowing), the way a sound is made (imitation), or nobody (chance). For each story they list what evidence would favour it: the history of the word, the sound pattern, and relatives in other languages."},{"tool":"Payoff Matrices","level":"full","move":"Students fill a two-by-two table for traders in two neighbouring markets who each choose which language to trade in. Both do best when both pick the same, though each would rather it was its own. They read the two matching cells, ask what could move both to one, and name what the table leaves out."},{"tool":"Analogy Mapping","level":"full","move":"Students map a tree of languages beside a tree of living things. Rows: shared ancestor, branching, change along a branch. The break column uses the Descent and Inheritance notes and the Language Family note: languages borrow across branches and can be changed on purpose. They test the map against a second picture, streams that join and split, to see which picture fits borrowing better."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
