INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
VALUES ('19fe4450-380b-5a74-bbac-35de01bad5e7', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'substrand', 'What Can We Conclude From Differences Between Languages', 'Key concepts: Knowledge, Meaning, Representation, Metacognition, Analogical Reasoning, Language, Translation, Multilingualism, Information, One Word, Two Meanings, Language of Instruction', '9-12', 'Language Arts, Social Studies, Computer Science, Science', '{"source_id":"OE-STRAND-oe-interdisciplinary-k12-languages-of-being-human-912","track":"extension-strands","required":true,"performanceIndicators":["Evaluates a claim that speakers of different languages think differently, separates a weaker and a stronger version of it, and says what evidence each needs.","Explains why languages from one family or region are not fully independent examples, and how that changes what a pattern across them shows.","Reads a table of meanings that share one word in some languages and states what it can suggest and what it cannot show about how speakers think.","Analyses a translation of a key idea, such as evolution or agency, into another language, finds where the ranges of meaning differ, and states what a reviewer who speaks both languages has to check.","Evaluates what machine translation does well and badly on a technical text, including for languages with little written text, and why fluent output alone does not settle whether the software understands.","Explains how the loss of a language affects what a community can pass on, and how the choice of language of instruction bears on it."],"concepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-knowledge","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-meaning","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-representation","emphasis":"primary"},{"id":"OE-SANDBOX-CONCEPT-000011","emphasis":"reinforcing"},{"id":"OE-SANDBOX-CONCEPT-000013","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-language","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-translation","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-multilingualism","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-information","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-one-word-two-meanings","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-language-of-instruction","emphasis":"reinforcing"}],"organizingConcepts":[{"id":"OE-CONCEPT-oe-interdisciplinary-oc-information-technology","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-information","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-learning-discovery","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-oc-culture-social","emphasis":"reinforcing"}],"organizingConceptsNote":"AI-drafted on 2026-10-30 from the stage links in content.concepts. No subject-matter expert has reviewed it.","guardrails":["Do not treat a word that two languages have in common as evidence that the speakers think alike.","Do not present a translation table as a set of equivalents. Show it as a draft that a speaker of both languages has to check.","Do not say that translation or language software understands, and do not say it cannot. Whether it does is debated, and fluent output alone does not settle it.","Do not claim how speakers of a named language think or live from features of their language. Word examples are fine once a speaker has checked them."],"assessmentItem":{"prompt":"A study says that the languages in its sample all use one word for two meanings, so people everywhere link the two ideas. List what is wrong or missing in this conclusion, using what you know about how languages are related.","goodAnswerShows":"Notes that related languages are not fully independent samples, that a word two languages have in common is not the same as a shared idea, and asks about sample size and spread.","commonMisreading":"Rejecting the whole study as worthless. The part asks for a measured reading: what the pattern can still suggest."},"thinkingTools":[{"tool":"Tinbergen''s Questions","level":"extended","move":"Students turn the grid on a popular claim: that people whose language has no word for an idea cannot think it. They ask what sets the claim off, how people come to believe it, how it spreads, and what it does for those who repeat it. They write the claim again in a form that can be tested."},{"tool":"Causal Mapping","level":"extended","move":"Students map the claim that language shapes thought: a language''s categories shape habits of attention, and habits shape behaviour. They add other causes of the same pattern: shared history, geography, writing and schooling. They add an arrow in the other direction, from what matters to a community to the words it has. They draw shared ancestry as a hidden common cause across a sample of related languages. Each arrow says who or what decides it, and a note says that a difference between groups describes averages and says little about any one speaker."},{"tool":"Payoff Matrices","level":"extended","move":"Students fill a table for two families that each choose which language to use at home with children. The best choice for each family depends on what the other does and on what school and work reward. They compare outcomes now and a generation later, and list what the table leaves out, such as pride, identity, pressure and policy."},{"tool":"Analogy Mapping","level":"extended","move":"Students compare a human translator and a machine translator on a technical passage. Rows: what is kept, what is left out, who checks. The break column uses the Meaning note and the Translation note: fluent output alone does not settle whether software understands, and quality drops for languages with little written text. They keep or drop the words ''understands'' and ''knows'' and say what evidence would decide."}],"literature_ids":[],"sources_note":"Sources are attached by a follow-up migration once LiteratureBase holds them.","draft_note":"AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it."}'::jsonb, 'draft') ON CONFLICT (id) DO NOTHING;
