-- 3. Order between parts, and links from existing parts (all proposed)
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'bffa8eae-478f-52ae-a5fd-b7ff43840af0', '495058e6-87bd-59ae-a20d-bc2d291fff41', 'prerequisiteOf', 'asserted', 'The 3-5 part compares settings, which needs the K-2 idea that people help each other learn.', 'proposed') ON CONFLICT DO NOTHING;
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', '495058e6-87bd-59ae-a20d-bc2d291fff41', '712e4748-73c1-5809-8cbe-8fa0528b138b', 'prerequisiteOf', 'asserted', 'The 6-8 part asks why societies organise schools, which builds on comparing the ways learning is organised.', 'proposed') ON CONFLICT DO NOTHING;
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', '712e4748-73c1-5809-8cbe-8fa0528b138b', 'a9c1777a-a159-534d-b927-ad30da661ce6', 'prerequisiteOf', 'asserted', 'The 9-12 part evaluates claims about the effects of schooling, which needs the purposes and the written, taught and learned curriculum from 6-8.', 'proposed') ON CONFLICT DO NOTHING;
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', '5b73aa4d-166f-5856-bd57-b6e9aa396bde', '31b3931a-5cfe-5bdd-9a66-5fa460a63392', 'prerequisiteOf', 'asserted', 'The 3-5 part follows words as they travel, which needs the K-2 idea that a word is an agreement within a group.', 'proposed') ON CONFLICT DO NOTHING;
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', '31b3931a-5cfe-5bdd-9a66-5fa460a63392', '96a0304e-2ff9-54cb-bbb1-1b03d521e818', 'prerequisiteOf', 'asserted', 'The 6-8 part explains why languages are alike, which builds on borrowing and shifting meaning from 3-5.', 'proposed') ON CONFLICT DO NOTHING;
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', '96a0304e-2ff9-54cb-bbb1-1b03d521e818', '19fe4450-380b-5a74-bbac-35de01bad5e7', 'prerequisiteOf', 'asserted', 'The 9-12 part evaluates conclusions drawn from language differences, which needs the family and borrowing ideas from 6-8.', 'proposed') ON CONFLICT DO NOTHING;
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'db1fca08-0dcf-5910-a3df-2de902e8630a', '31b3931a-5cfe-5bdd-9a66-5fa460a63392', 'foundationalTo', 'asserted', 'Passing a message along a chain is a classroom-sized case of transmission with variation, which the Strand 1 3-5 part introduces.', 'proposed') ON CONFLICT DO NOTHING;
INSERT INTO lpm_connections (project_id, branch_id, from_object_id, to_object_id, relation_type, kind, rationale, status) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'ad0173a4-5c64-5d05-96ac-2b61810c4153', '712e4748-73c1-5809-8cbe-8fa0528b138b', 'foundationalTo', 'asserted', 'The Strand 3 6-8 part introduces institutions as structures that keep practices going. The schooling part applies that to schools.', 'proposed') ON CONFLICT DO NOTHING;

-- 4. Threads. Strand threads first (the Strands page reads these), then storyline threads, then thinking-tool threads
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('4ac3eb9e-7f4f-5bf8-9dba-c2c0b2cf12e7', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'nature-of-schooling', 'The Nature of Schooling', 'vertical_horizontal', 'Education is wider than schooling. Learning, teaching, education and schooling are four different things, and the strand keeps them apart from the first part to the last.', 'Every society passes knowledge to its next generation. Schools are several thousand years old and were for a few children. Schooling for nearly every child is recent, a matter of the last two centuries or so, and began at different times in different countries. This strand asks what is passed on, who teaches, who decides and for whose benefit, in many settings, with schools treated as one case among several. It reuses Teaching, Scaffolding, Institutions, Norms, Knowledge and Development, which the first four strands use but never place at the centre of a part. It does not treat school as the standard that other ways of learning are measured against, and it does not claim that schooling is an adaptation. Many children still have no place in a school and many families want one, so missing school is also a question of justice. Questions that run through the bands: How do people learn, and who or what helps? What separates learning, teaching, education and schooling? Who decides what is worth passing on? What are schools for, and what happens when their purposes conflict? How do tools, including AI, change what can be passed on? The 6-8 and 9-12 parts use a layered frame of purposes (the learner, the family, the community, the school, the nation, the world and future generations) and allow the layers to disagree. The 9-12 part asks where evolutionary accounts of teaching and transmission have been applied to schools, and where critics say they leave out justice, care, power and who decides.', NULL, 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.', ARRAY[]::text[], 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
