VALUES ('0e50000d-60f2-56c5-b7d7-e415eba6a1ac', '4ac3eb9e-7f4f-5bf8-9dba-c2c0b2cf12e7', 'a9c1777a-a159-534d-b927-ad30da661ce6', 4, '9-12, Education as a Changing System. Key concepts: Institutions, Selection, Transmission, Innovation, Knowledge, Culture, Educational Purpose, Curriculum, Learning, Metacognition, Technology.', NULL, NULL)
