INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('477e5314-0f68-5f3d-8205-8ab029459dfe', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'languages-of-being-human', 'The Languages of Being Human', 'vertical_horizontal', 'Words are shared habits within a community. One word can carry several meanings, one meaning can have several words, and similar words in two languages can come from shared ancestry, borrowing or chance.', 'Every human group has language. Languages differ in how they package meanings, and they share a great deal. This strand asks how language carries knowledge across people and time, how languages change and relate, and what can and cannot be concluded from differences between them. It reuses Communication, Representation, Information, Signal, Cue and Meaning, which the information work of October 2026 placed in the model, and gives them a concrete subject. Sign languages count as full languages from the first part. Questions that run through the bands: How can many different words and signs do the same job? How does a message change as it passes from person to person? Why are two languages alike: shared ancestry, borrowing or chance? What does a word mean, and what is lost in translation? What can differences between languages show about how people think, and what can they not show? The 9-12 part treats the question of independent samples as a statistics lesson: languages in one family share ancestry and neighbours share contact, so agreement among them is weaker evidence than it looks.', NULL, 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.', ARRAY[]::text[], 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
