INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('7280c80e-442e-58dd-9493-2e21b8b43d52', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'who-decides-what-is-passed-on', 'Who decides what is passed on', 'vertical_horizontal', 'In every society someone or something shapes what the next generation gets to learn. The thread follows that choice from copying in a group, through institutions, to curricula and AI.', 'In every society someone or something shapes what the next generation gets to learn. The thread follows that choice from copying in a group, through institutions, to curricula and AI. AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.', NULL, 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.', ARRAY[]::text[], 'proposed')
