INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('c4b12be0-6f89-5ba0-9aee-4dba458164bb', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'language-of-instruction-and-who-can-learn', 'Language of instruction and who can learn', 'vertical_horizontal', 'Schools choose a language for lessons, and the choice affects who follows, who is heard and which languages are passed on. The thread joins the two new strands.', 'Schools choose a language for lessons, and the choice affects who follows, who is heard and which languages are passed on. The thread joins the two new strands. AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.', NULL, 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it.', ARRAY[]::text[], 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d530a44f-439a-5668-8208-6c3b44bd3627', 'c4b12be0-6f89-5ba0-9aee-4dba458164bb', '712e4748-73c1-5809-8cbe-8fa0528b138b', 1, '6-8, Why Societies Build Schools. Students describe how a choice of language of instruction helps some learners and makes learning harder for others.', NULL, 'Leads into Languages Have Families and Neighbours.')
