INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d8e4c166-4476-5608-8e8c-1ce76674ec4f', 'c4b12be0-6f89-5ba0-9aee-4dba458164bb', 'a9c1777a-a159-534d-b927-ad30da661ce6', 4, '9-12, Education as a Changing System. Students bring language choices into an analysis of purposes at several levels.', NULL, NULL)
