INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('27371746-4f4a-5b31-9bda-b0aa688c5932', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-tinbergen-extension-strands', 'Thinking tool: Tinbergen''s Questions (Schooling and Languages strands)', 'vertical_horizontal', 'The Guide''s questions in plain words for each band. K-2 uses two cards: what is it for, and what came before it. 3-5 adds what is happening right now and how a learner got good at it. 6-8 uses four rows: what does it do for the people involved, how does it run today, how did a learner come to it, and where did it come from over many years. 9-12 uses the full grid with inside and outside causes, may rename rows for machines, and lets ''unknown'' be an answer. Rows that do not apply are marked empty with a reason.', 'Tinbergen''s Questions in the two extension strands. Role here: primary. Both strands study things that pass between people (skills, schools, words), so the questions about where something came from and what it does are central. The Guide''s wording is renamed here for learning and for language. Form: The Guide''s questions in plain words for each band. K-2 uses two cards: what is it for, and what came before it. 3-5 adds what is happening right now and how a learner got good at it. 6-8 uses four rows: what does it do for the people involved, how does it run today, how did a learner come to it, and where did it come from over many years. 9-12 uses the full grid with inside and outside causes, may rename rows for machines, and lets ''unknown'' be an answer. Rows that do not apply are marked empty with a reason. What it must not bring in: A school or a language is never called a species or an organism. A tool or an app gets no wants and no family. Near causes and far causes are never ranked by importance. A function answer never stands in for a how answer. A word is not said to have a purpose of its own: the purpose belongs to the people who use it.', 'Which row is this answer in: what sets it off now, how a learner got good at it, how it was passed on, or what it does for the people involved? Does the row mean the same thing for a school, a word and a tool?', 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it. No evidence source is attached to the stations yet. MethodsBase record: OE-METHOD-tinbergens-questions.', ARRAY['No study of children under 11 using these questions on learning or language was found.', 'The K-2 and 3-5 wording is a proposal for a teacher or researcher to test.']::text[], 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('0ce514d0-6593-59d5-a35a-776a95c7b35a', '27371746-4f4a-5b31-9bda-b0aa688c5932', 'bffa8eae-478f-52ae-a5fd-b7ff43840af0', 1, 'K-2, People Who Show Us How in The Nature of Schooling (precursor). Children choose something they learned, such as tying a shoe, cooking rice or a song. Two question cards guide them: what is it for, and who or what helped, if anyone? They place picture cards on a strip: now, when I was little, before I was born. Example: Tying a shoe, and a family recipe that two cousins both cook. Shown as: Two question cards and picture cards on a three-part strip. New demand: First sorting of where a skill came from, with a person at each step. Children give purpose answers readily at this age, so the function card stays simple. Concepts: Learning, Teaching.', '241ac4b1-00b3-517c-b3b5-10029f1efdc6', 'Leads into Many Ways to Say It (K-2).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('1a4b0540-b3e6-57b9-aea9-8913f00d12dc', '27371746-4f4a-5b31-9bda-b0aa688c5932', '5b73aa4d-166f-5856-bd57-b6e9aa396bde', 2, 'K-2, Many Ways to Say It in The Languages of Being Human (precursor). Children compare a greeting word from a home language, a sign and a bird''s alarm call. For each they answer what is it for and who passed it on. They see that a person taught the greeting and that people in the group use it the same way. Example: A greeting in two languages or signs, and a bird''s alarm call. Shown as: Picture cards with a ''who passed it on'' sticker for each. New demand: Keep a word that a group uses by shared habit apart from a call. Adults help, because the line between learned and inborn calls is not simple and the lesson does not need to settle it. Concepts: Communication, Signal, Language.', '301b8eed-edd6-5c71-91df-5219467c24fb', 'Leads into Why Societies Build Schools (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('80c770da-9781-54fe-b780-df027849fc22', '27371746-4f4a-5b31-9bda-b0aa688c5932', '712e4748-73c1-5809-8cbe-8fa0528b138b', 3, '6-8, Why Societies Build Schools in The Nature of Schooling (full). Students put a school and a family workshop side by side in a two-column grid. Rows: what it does for the people involved, how it runs day to day, how a learner comes to it over the years, and where it came from over many years. Rows that do not fit are marked empty with a reason. Example: A school with a timetable and bells, and a family workshop where a young person learns by helping. Shown as: Two-column grid with four rows and an ''empty, because'' note. New demand: Keep the answer about what it does for people apart from the answer about how it runs. Neither setting is called better. Concepts: Schooling, Apprenticeship, Institutions, Education.', '7f3313a9-e131-5cd9-9e88-3adabd9c26ce', 'Leads into Languages Have Families and Neighbours (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('96946e55-be28-55af-8f4c-5db7494e3136', '27371746-4f4a-5b31-9bda-b0aa688c5932', '96a0304e-2ff9-54cb-bbb1-1b03d521e818', 4, '6-8, Languages Have Families and Neighbours in The Languages of Being Human (full). Students ask four questions about one word that travelled between languages: what is it used for, how is it said and understood today, how does a child come to know it, and where did it come from over centuries. They mark how the word reached each language: inherited from an ancestor or borrowed. Example: The two main forms of the word for tea, ''te'' and ''cha'', both from Chinese. ''Te'' came from Min Nan and spread with Dutch sea trade. ''Cha'' came from Mandarin and Cantonese and spread overland and through Portuguese traders from Macau. A linguist must confirm the example before use. Shown as: Four-row grid with a ''route'' note under the history row. New demand: Separate how a word is used today from how it arrived. History answers do not explain use, and use does not explain history. Concepts: Borrowing, Language Evolution, Word Meaning.', 'e1f5fc1b-7ae8-5267-854a-6394b7e4d7cb', 'Leads into Education as a Changing System (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('7cb50741-9bd8-5ec4-ae8a-cc6538c0395b', '27371746-4f4a-5b31-9bda-b0aa688c5932', 'a9c1777a-a159-534d-b927-ad30da661ce6', 5, '9-12, Education as a Changing System in The Nature of Schooling (extended). Students take one AI tool used for study and ask the grid questions. Rows are renamed for machines: inputs and rules, training and updates, lineage of versions, and what builders and learners gain. They mark rows that do not apply and rows where the answer is unknown, such as the training data. Example: An AI writing helper offered to students, across several versions. Shown as: Grid with renamed rows, ''empty because'' and ''unknown'' marks. New demand: Say row by row where a question stops meaning the same thing for a student, a teacher and a tool. ''Unknown'' counts as an answer. Concepts: Technology, Learning, Curriculum, Institutions.', '1d89ba05-d574-53ea-aaa9-c513d9125e96', 'Leads into What Can We Conclude From Differences Between Languages (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('1f165514-400f-5ace-a17f-afe2d3513157', '27371746-4f4a-5b31-9bda-b0aa688c5932', '19fe4450-380b-5a74-bbac-35de01bad5e7', 6, '9-12, What Can We Conclude From Differences Between Languages in The Languages of Being Human (extended). Students turn the grid on a popular claim: that people whose language has no word for an idea cannot think it. They ask what sets the claim off, how people come to believe it, how it spreads, and what it does for those who repeat it. They write the claim again in a form that can be tested. Example: A repeated saying that one language has many words for one thing and another has none. Shown as: Five-row grid applied to the claim, with the rewritten claim beside it. New demand: Use the grid on a habit of thought, and judge each answer by its row. A claim can be popular and still fail when tested. The strong version, that people cannot think what they have no word for, mostly fails, and weaker effects have mixed evidence. Concepts: Meaning, Metacognition, Knowledge.', '75b8a947-bdc4-529b-a909-b2d63dd87005', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('aa4372d6-7331-54e1-91c2-ea6d40ce5b55', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-causal-extension-strands', 'Thinking tool: Causal Mapping (Schooling and Languages strands)', 'vertical_horizontal', 'Factors joined by arrows with plus and minus signs, loops and delays, as in the existing causal-mapping thread. In these strands each arrow also says who or what decides it: a person, a rule someone wrote, or nobody. Measured arrows and supposed arrows are shown differently once claims about effects appear.', 'Causal Mapping in the two extension strands. Role here: supporting. Both strands rest on questions about what causes what: what makes help fade, what changes a message, what a school changes in a society, what a language does to thought. Causal maps make hidden assumptions and common causes visible. Form: Factors joined by arrows with plus and minus signs, loops and delays, as in the existing causal-mapping thread. In these strands each arrow also says who or what decides it: a person, a rule someone wrote, or nobody. Measured arrows and supposed arrows are shown differently once claims about effects appear. What it must not bring in: No arrow gives a school, a word or a language a goal. No loop is read as foresight. A correlation across countries is not drawn as an arrow without a note that it is supposed. A hidden controller is not accepted as an explanation of a group pattern.', 'Which arrows were measured and which are guesses? Who or what decides this arrow? What else could produce the same pattern?', 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it. No evidence source is attached to the stations yet. MethodsBase record: OE-METHOD-causal-mapping.', ARRAY['Evidence for causal mapping at ages 8 to 10 comes from studies on other topics.', 'The maps about schooling and income depend on data that a reviewer has to supply.']::text[], 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('acd9018d-9787-5e97-b1dc-b646b152020d', 'aa4372d6-7331-54e1-91c2-ea6d40ce5b55', '495058e6-87bd-59ae-a20d-bc2d291fff41', 1, '3-5, Many Places to Learn, Many Ways to Teach in The Nature of Schooling (full). Students extend the learner-helper loop (skill rises, help falls) to two settings: a lesson at school and learning beside an older relative at work. Each arrow gets a sign. Each arrow is also marked with who decides it: the teacher''s plan, the helper''s judgement or nobody. Example: Learning to cook a family dish beside a relative, and learning a maths method in a lesson. Shown as: Moving cards on a poster, arrows with plus or minus, a coloured dot for who decides. New demand: Read the same pattern in two settings, help falling as skill rises, and see that the shape is similar and the decider differs. Concepts: Scaffolding, Teaching, Learning.', 'e09d4837-14bf-5d3f-839f-f708e982b216', 'Leads into Words Travel and Change (3-5).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('09f5edb4-e257-55eb-8b88-18249a7d5b5a', 'aa4372d6-7331-54e1-91c2-ea6d40ce5b55', '31b3931a-5cfe-5bdd-9a66-5fa460a63392', 2, '3-5, Words Travel and Change in The Languages of Being Human (full). Students map the message chain from the strand. A noisy room lowers how well each person hears. Interest raises how much detail they add. Each arrow is marked by colour: nobody chose it (mishearing) or a person chose it (retelling in their own words). Example: A whispered message passed along five children. Shown as: Factor cards with plus and minus arrows in two colours. New demand: Tell changes nobody chose from changes a person chose, and name one way the game exaggerates drift: nobody can ask "what?". Concepts: Transmission, Variation, Communication.', '0a1dc107-eeca-53a2-8a29-056c0f7b70df', 'Leads into Why Societies Build Schools (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('db509195-c897-596b-83e0-75dec0398660', 'aa4372d6-7331-54e1-91c2-ea6d40ce5b55', '712e4748-73c1-5809-8cbe-8fa0528b138b', 3, '6-8, Why Societies Build Schools in The Nature of Schooling (full). Students map why people at a school add or drop a subject: families ask for it, teachers are available or not, hours in the day are fixed, and an exam rewards some subjects. They mark the delay between a request and a timetable change, and who decides each arrow. Example: People at a school deciding whether to add a computing or language class. Shown as: Factor cards, arrows with signs, a delay mark and a decider dot. New demand: Add a fixed quantity (hours in a day) that makes more of one subject mean less of another, and a delay. Concepts: Institutions, Curriculum, Educational Purpose.', '4ebf512e-ba71-59c4-8e93-e03007a9d829', 'Leads into Languages Have Families and Neighbours (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('39c2761c-8f70-5fde-a3c3-cacf40873c5c', 'aa4372d6-7331-54e1-91c2-ea6d40ce5b55', '96a0304e-2ff9-54cb-bbb1-1b03d521e818', 4, '6-8, Languages Have Families and Neighbours in The Languages of Being Human (full). Students draw four different causal stories for one word that two languages have in common: common ancestor, borrowing, imitation of a sound or baby talk, and chance. Each arrow says who or what decides it: children learning the word from their families (ancestor), speakers choosing to take it over (borrowing), the way a sound is made (imitation), or nobody (chance). For each story they list what evidence would favour it: the history of the word, the sound pattern, and relatives in other languages. Example: One word that two neighbouring languages share, with its history hidden until the end. Shown as: Four small maps side by side, each with an ''evidence that would favour it'' list. New demand: Compare four explanations of one fact, name the evidence that would separate them, and mark who or what decides each arrow. Concepts: Borrowing, Inheritance, Language Family.', 'e1f5fc1b-7ae8-5267-854a-6394b7e4d7cb', 'Leads into Education as a Changing System (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('23a4ab88-d9e9-5d73-8431-5b63e1258644', 'aa4372d6-7331-54e1-91c2-ea6d40ce5b55', 'a9c1777a-a159-534d-b927-ad30da661ce6', 5, '9-12, Education as a Changing System in The Nature of Schooling (extended). Students map the claim that more years of schooling raise income. They add other causes that could produce the same pattern: family wealth, local jobs, and income paying for more schooling. They mark each arrow as measured or supposed, say who decides it (employers, families, a government or nobody), and name a study that could help separate them. Example: A report that countries with more years of schooling have higher incomes. Shown as: Factor cards, arrows with signs, solid lines for measured and dashed lines for supposed. New demand: Include a reverse arrow and a shared cause, and name a study design. Evidence at this age is better than for younger bands, and the data still need a reviewer. Concepts: Institutions, Knowledge, Educational Purpose.', '4ebf512e-ba71-59c4-8e93-e03007a9d829', 'Leads into What Can We Conclude From Differences Between Languages (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d2cf0975-f698-5a49-ac8d-c2f3f55a7c0b', 'aa4372d6-7331-54e1-91c2-ea6d40ce5b55', '19fe4450-380b-5a74-bbac-35de01bad5e7', 6, '9-12, What Can We Conclude From Differences Between Languages in The Languages of Being Human (extended). Students map the claim that language shapes thought: a language''s categories shape habits of attention, and habits shape behaviour. They add other causes of the same pattern: shared history, geography, writing and schooling. They add an arrow in the other direction, from what matters to a community to the words it has. They draw shared ancestry as a hidden common cause across a sample of related languages. Each arrow says who or what decides it, and a note says that a difference between groups describes averages and says little about any one speaker. Example: A study that compares speakers of a few related languages on a task. Shown as: Factor cards and arrows with a hidden-cause box, measured and supposed arrows in different styles. New demand: Show why related languages are not fully independent examples, as a common cause on the map. Concepts: Language Family, Meaning, Knowledge.', 'cb666457-4ecf-5c4e-be1b-e2aa2f956d51', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('37542692-67e6-5244-bf1f-ff6d893c108c', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-payoff-extension-strands', 'Thinking tool: Payoff Matrices (Schooling and Languages strands)', 'vertical_horizontal', 'A table of outcomes for each pair of choices by two parties, as in the existing payoff thread. Every table says whose choice it is and whether choice is the right word. These strands use ranked outcomes (best, middle, worst) before numbers. Outcomes are worded in plain terms and carry a ''what this table leaves out'' note.', 'Payoff Matrices in the two extension strands. Role here: limited. Coordination and cost-sharing problems sit under both subjects: agreeing on a word, deciding who teaches, choosing a language of instruction. A small table shows why individually sensible choices can add up to outcomes nobody wanted. It is a limited tool here. Form: A table of outcomes for each pair of choices by two parties, as in the existing payoff thread. Every table says whose choice it is and whether choice is the right word. These strands use ranked outcomes (best, middle, worst) before numbers. Outcomes are worded in plain terms and carry a ''what this table leaves out'' note. What it must not bring in: No table gives a language, a school or a custom a choice or a reason. Human cases are not used as evidence for what evolved. A model of language shift or schooling is never presented as a prediction for any particular community, and no particular community is named. Fairness and identity are named as left out and never silently counted as payoffs.', 'Who is choosing here, and is choosing the right word? What is left out of the table: pride, identity, pressure, rules?', 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it. No evidence source is attached to the stations yet. MethodsBase record: OE-METHOD-payoff-matrices.', ARRAY['No study of students under 11 using payoff tables for coordination was found.', 'Whether payoff tables help students think about language choice has not been tested.']::text[], 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('8fbe4478-5b72-53af-8a51-95c7858bc5cc', '37542692-67e6-5244-bf1f-ff6d893c108c', '5b73aa4d-166f-5856-bd57-b6e9aa396bde', 1, 'K-2, Many Ways to Say It in The Languages of Being Human (precursor). Two children each pick one of two made-up words for ''start the game''. A picture table with face cards shows what happens when both pick the same word and when they pick different words. Children say which outcomes they like and what they could do to match. Example: Two children who invent ''go'' and ''now'' as a signal to begin. Shown as: Picture table with face cards, one row per choice. New demand: First outcome table where the good result needs both children to match. Long-term columns are left out. Evidence for this age is thin. Concepts: Communication, Language, Cooperation.', '301b8eed-edd6-5c71-91df-5219467c24fb', 'Leads into Languages Have Families and Neighbours (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('517a448d-a715-5838-9e97-c0e9c51ac00c', '37542692-67e6-5244-bf1f-ff6d893c108c', '96a0304e-2ff9-54cb-bbb1-1b03d521e818', 2, '6-8, Languages Have Families and Neighbours in The Languages of Being Human (full). Students fill a two-by-two table for traders in two neighbouring markets who each choose which language to trade in. Both do best when both pick the same, though each would rather it was its own. They read the two matching cells, ask what could move both to one, and name what the table leaves out. Example: Traders in two market towns choosing a trade language. Shown as: Two-by-two table with best, middle and worst, and a ''left out'' note. New demand: Find a table where both matching cells are good and the choice between them is open. Choosing is the right word for traders and the wrong word for a child learning a first language. Concepts: Language, Communication, Cooperation, Institutions.', 'dcacbe0f-6ddd-58b1-b63a-a91ebb7e46ee', 'Leads into Why Societies Build Schools (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('91eb41b2-9102-55f0-9c17-dff2b0e7df5c', '37542692-67e6-5244-bf1f-ff6d893c108c', '712e4748-73c1-5809-8cbe-8fa0528b138b', 3, '6-8, Why Societies Build Schools in The Nature of Schooling (full). Students fill a table in which an education authority picks the language for lessons (the home language, a wider language, or both) and families then choose to enrol, move or pay for a school elsewhere. Cells rank outcomes best, middle and worst for learners, families and the authority, now and later. They look for an arrangement that none of the sides proposed at first. Example: An authority choosing a language of instruction and families responding, with no particular place named. Shown as: Table with ranked outcomes in the cells, a ''later'' column and a ''left out'' note. New demand: The table depends on assumptions the students list. Left out: who holds power, and a child''s right to follow the lesson. Choosing is the right word for the authority, and families may have no other school nearby. Concepts: Language of Instruction, Educational Purpose, Multilingualism, Institutions.', '6f6f678e-5069-5e01-b317-3f31a2f572f3', 'Leads into Education as a Changing System (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('30ec9783-8edb-5ec7-a3ea-e849c2704413', '37542692-67e6-5244-bf1f-ff6d893c108c', 'a9c1777a-a159-534d-b927-ad30da661ce6', 4, '9-12, Education as a Changing System in The Nature of Schooling (extended). Students fill a table for two adults who can each spend time teaching a child or doing other work. Both gain if the child learns. Each gains most if the other carries the teaching. They compare ways a group might handle it: a custom, a shared payment, a school, or children learning alongside the work. They say which of these the table fits and which it misses. Example: Two households in a community deciding who teaches a skill to the children. Shown as: Two-by-two table, then a changed table after each way out. New demand: Read why a group may set up a shared arrangement, and state that the table is a model of one explanation. It is not evidence that schools arose this way, and it leaves out children who learn by joining the work. Evidence for this skill at ages 15 to 18 is thin. Concepts: Teaching, Cooperation, Institutions, Norms.', 'b0040254-6692-5ff3-8c4a-41b7a0bd1e51', 'Leads into What Can We Conclude From Differences Between Languages (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('6acf28b7-a941-5bd3-b775-2359f776ec68', '37542692-67e6-5244-bf1f-ff6d893c108c', '19fe4450-380b-5a74-bbac-35de01bad5e7', 5, '9-12, What Can We Conclude From Differences Between Languages in The Languages of Being Human (extended). Students fill a table for two families that each choose which language to use at home with children. The best choice for each family depends on what the other does and on what school and work reward. They compare outcomes now and a generation later, and list what the table leaves out, such as pride, identity, pressure and policy. Example: Two families in a place with a dominant language, with no particular community named. Shown as: Two-by-two table with ''now'' and ''a generation later'' columns and a ''left out'' list. New demand: Say that the table makes no prediction about any particular community and that loss of a language is not inevitable. Name which assumptions would change the result. Concepts: Multilingualism, Language of Instruction, Norms, Culture.', '785dd3d3-9b2f-52b3-99f0-1f665a3743a1', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
VALUES ('74fbb91a-36d9-536e-b96d-dbea41ca7293', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'thinking-tool-analogy-extension-strands', 'Thinking tool: Analogy Mapping (Schooling and Languages strands)', 'vertical_horizontal', 'Two or more cases from different domains side by side, shared relations in rows, and a ''where it breaks'' column filled from the vocabulary''s ''does not carry over'' notes. Where a concept has no such note, the map names the neighbouring note it borrows. A map is a hypothesis that needs separate evidence. K-2 starts with picture cards sorted into same job, looks alike and different.', 'Analogy Mapping in the two extension strands. Role here: primary. Both strands rest on comparisons that are tempting and partly wrong: schools and scaffolds, language and living things, translators and language models. Analogy mapping gives students a way to use a comparison and to say where it fails. Form: Two or more cases from different domains side by side, shared relations in rows, and a ''where it breaks'' column filled from the vocabulary''s ''does not carry over'' notes. Where a concept has no such note, the map names the neighbouring note it borrows. A map is a hypothesis that needs separate evidence. K-2 starts with picture cards sorted into same job, looks alike and different. What it must not bring in: No map treats surface resemblance as evidence, and no map ends without a break column. A language model is never said to understand, or not to understand, without the debate being stated. ''Species'', ''offspring'' and ''fitness'' for schools or languages appear only as quoted words under test, and are kept or dropped after the break column is filled. Each map names the senses it joins.', 'Which rows match because the relations are the same, and which because the pictures look alike? Where does the map break, and which note says so?', 'AI-drafted on 2026-10-30 from the lab''s design note on the two strands. No linguist, anthropologist of learning, education researcher or speaker of the languages involved has reviewed it, and no classroom has used it. No evidence source is attached to the stations yet. MethodsBase record: OE-METHOD-analogy-mapping.', ARRAY['Naming a break between two cases is untested at ages 5 to 7.', 'The 9-12 maps need a reviewer who knows both domains.']::text[], 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('ef91e2ab-78f4-5d17-ae4d-94b17d352e1e', '74fbb91a-36d9-536e-b96d-dbea41ca7293', '5b73aa4d-166f-5856-bd57-b6e9aa396bde', 1, 'K-2, Many Ways to Say It in The Languages of Being Human (precursor). Children compare a handshake and a word with picture cards. They sort what is the same (both work because two people know the same rule) from what looks alike and what differs. An adult helps them name one difference. Example: A handshake and a greeting word. Shown as: Two picture cards and three sorting mats: same job, looks alike, different. New demand: Name one difference between two cases that share a job, as the Analogical Reasoning note asks. Relation words help. Naming a break is untested at this age. Concepts: Analogical Reasoning, Communication, Representation.', '7c75aef6-b615-572a-aa01-b2c82591cd2f', 'Leads into Many Places to Learn, Many Ways to Teach (3-5).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('fe411a38-eec7-530e-8787-715f5816c4e5', '74fbb91a-36d9-536e-b96d-dbea41ca7293', '495058e6-87bd-59ae-a20d-bc2d291fff41', 2, '3-5, Many Places to Learn, Many Ways to Teach in The Nature of Schooling (full). Students fill a two-column map: scaffolding on a building and the help a learner gets. Rows: what the support is for, when it is added, when it is taken away, who decides. The break column names the Teaching note, because Scaffolding has no note of its own: a wall takes no part in its own building, and a learner acts, can ask and can refuse. Example: Scaffolding around a wall being built, and an older child helping a younger one learn to swim. Shown as: Two-column table with four shared rows and a break column. New demand: Match on relations such as when support is added and removed. Name one break taken from the Teaching note. Concepts: Scaffolding, Teaching, Analogical Reasoning.', 'e09d4837-14bf-5d3f-839f-f708e982b216', 'Leads into Words Travel and Change (3-5).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('e7dad0f3-29a5-5efb-be33-97e6ca5b1802', '74fbb91a-36d9-536e-b96d-dbea41ca7293', '31b3931a-5cfe-5bdd-9a66-5fa460a63392', 3, '3-5, Words Travel and Change in The Languages of Being Human (full). Students map a word that moved from one language to another beside a tool that moved from one group to another. Rows: who holds it, who gets it, what changes on arrival, whether it can go back. The break column uses the Transmission note and the Borrowing note: nothing is handed back, and the new language reshapes the word to its own sounds. Example: A food word that travelled with the food, and a tool that was copied by a neighbouring group. Shown as: Two-column table with four rows and a break column. New demand: Match on relations, and name where borrowing differs from inheritance. Concepts: Borrowing, Transmission, Analogical Reasoning.', 'e1f5fc1b-7ae8-5267-854a-6394b7e4d7cb', 'Leads into Why Societies Build Schools (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('42613ff6-e978-52d7-8334-8783b95cb15d', '74fbb91a-36d9-536e-b96d-dbea41ca7293', '712e4748-73c1-5809-8cbe-8fa0528b138b', 4, '6-8, Why Societies Build Schools in The Nature of Schooling (full). Students compare three stand-ins for what some people chose to pass on: a written curriculum, a textbook and a teacher''s lessons. Rows: what is kept, what is left out, who treats it as a stand-in. The break column uses the Representation note and the Curriculum note: the written plan, the lesson given and the learning that results are three different things. Example: A national syllabus, a class textbook and a teacher''s lessons on the same topic. Shown as: Three-column table with rows for kept, left out and who reads it. New demand: Say who treats each item as a stand-in and what each leaves out, then name a use for which each would fail. Concepts: Curriculum, Representation, Knowledge.', '954e3407-019e-58b4-b72d-e7e967a5f20d', 'Leads into Languages Have Families and Neighbours (6-8).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('231442f9-8418-5675-8067-5659be4620fe', '74fbb91a-36d9-536e-b96d-dbea41ca7293', '96a0304e-2ff9-54cb-bbb1-1b03d521e818', 5, '6-8, Languages Have Families and Neighbours in The Languages of Being Human (full). Students map a tree of languages beside a tree of living things. Rows: shared ancestor, branching, change along a branch. The break column uses the Descent and Inheritance notes and the Language Family note: languages borrow across branches and can be changed on purpose. They test the map against a second picture, streams that join and split, to see which picture fits borrowing better. Example: A family of related languages beside a tree of related birds. Shown as: Two-column table with three relation rows, a break column and a second picture. New demand: Check the map against a second analogy, since one analogy can leave a wrong picture. Name where the tree hides what the streams show. Concepts: Language Family, Language Evolution, Inheritance, Borrowing.', 'cb666457-4ecf-5c4e-be1b-e2aa2f956d51', 'Leads into Education as a Changing System (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('3b33a52f-8da1-58f9-84be-88f99bd4884d', '74fbb91a-36d9-536e-b96d-dbea41ca7293', 'a9c1777a-a159-534d-b927-ad30da661ce6', 6, '9-12, Education as a Changing System in The Nature of Schooling (extended). Students test whether a teaching method spreading between schools works like a trait spreading in a population. They fill the break column first from the notes on Selection, Fitness, Inheritance and Institutions: who sets the target, whether versions are copied or designed, whether any lineage dies out. Then they fill the match column and keep or drop the words ''variation'', ''selection'' and ''fitness''. Example: A new teaching method that spreads between schools, beside a trait spreading in a population. Shown as: Table with columns for case A, case B and where it breaks, the break column filled first, and a keep-or-drop list of words. New demand: Fill the break column before the match column, then test the kept words on a second case, a market or a garden. Keep a word only if it survives both. Concepts: Selection, Institutions, Innovation, Analogical Reasoning.', '0573db35-8451-5189-998c-8619ea1d26ec', 'Leads into What Can We Conclude From Differences Between Languages (9-12).')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('405d88cb-3b6b-5c66-83e4-f1e6fb022b67', '74fbb91a-36d9-536e-b96d-dbea41ca7293', '19fe4450-380b-5a74-bbac-35de01bad5e7', 7, '9-12, What Can We Conclude From Differences Between Languages in The Languages of Being Human (extended). Students compare a human translator and a machine translator on a technical passage. Rows: what is kept, what is left out, who checks. The break column uses the Meaning note and the Translation note: fluent output alone does not settle whether software understands, and quality drops for languages with little written text. They keep or drop the words ''understands'' and ''knows'' and say what evidence would decide. Example: A short passage about a scientific idea, translated by a person and by software, and read by someone who knows both languages. Shown as: Two-column table with rows for kept, left out and who checks, and a keep-or-drop list. New demand: Fill the break column first. Test the kept words on a second case, a traveller using a phrasebook. Keep a word only if it survives both. Concepts: Translation, Meaning, Representation, Technology.', 'ef3118e2-59b7-53d7-818d-1b4fe9ef1736', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;

